  "core.settingPreferRemoteDesc": "\u5148\u5728\u4E0A\u8FF0\u670D\u52A1\u5668\u4E0A\u67E5\u627E\u5A92\u4F53\uFF0C\u518D\u67E5\u627E\u5E93\u548C\u5A92\u4F53\u6587\u4EF6\u5939\uFF1B\u53EA\u6709\u5728\u6CA1\u6709\u670D\u52A1\u5668\u5B58\u6709\u8BE5\u6587\u4EF6\u6216\u90FD\u65E0\u54CD\u5E94\u65F6\uFF0C\u624D\u4F7F\u7528\u5E93\u4E2D\u7684\u526F\u672C\u3002\u9002\u7528\u4E8E\u672C\u5730\u526F\u672C\u5B58\u653E\u5728 iCloud\u3001\u64AD\u653E\u524D\u9700\u8981\u5148\u4E0B\u8F7D\u7684\u60C5\u51B5\u3002",
